package com.ifound;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import jakarta.inject.Inject;
import jakarta.ws.rs.*;
import jakarta.ws.rs.core.MediaType;
import java.util.*;
import java.sql.*;
@Path("/api") @Produces(MediaType.APPLICATION_JSON) @Consumes(MediaType.APPLICATION_JSON)
public class AuthResource {
 @Inject io.agroal.api.AgroalDataSource database;
 @Inject AuthService auth;@Inject ObjectMapper mapper;
 @HeaderParam("Authorization")String authorization;@HeaderParam("X-Session-Token")String token;
 @POST @Path("/auth/login") public Object login(JsonNode request)throws Exception{auth.service(authorization);return auth.login(ComplianceEngine.required(request,"username",64),ComplianceEngine.required(request,"password",200));}
 @GET @Path("/auth/me") public Object me(){return Map.of("user",auth.user(authorization,token));}
 @POST @Path("/auth/logout") public Object logout()throws Exception{var user=auth.user(authorization,token);auth.logout(user,token);return Map.of("ok",true);}
 @GET @Path("/users") public JsonNode users()throws Exception{auth.admin(auth.user(authorization,token));var result=mapper.createArrayNode();try(var c=database.getConnection();var q=c.prepareStatement("SELECT id,username,role,active FROM app_users ORDER BY username");var r=q.executeQuery()){while(r.next()){var row=result.addObject();row.put("id",r.getString(1));row.put("username",r.getString(2));row.put("role",r.getString(3));row.put("active",r.getBoolean(4));}}return result;}
 static String role(JsonNode request){String role=ComplianceEngine.required(request,"role",20);if(!Set.of("Admin","Reviewer","Viewer").contains(role))throw new BadRequestException("Use Admin, Reviewer or Viewer role.");return role;}
 @POST @Path("/users") public Object create(JsonNode request)throws Exception{var actor=auth.user(authorization,token);auth.admin(actor);String name=AuthService.username(ComplianceEngine.required(request,"username",64)),role=role(request),password=AuthService.hash(ComplianceEngine.required(request,"password",200)),id=UUID.randomUUID().toString();try(var c=database.getConnection()){c.setAutoCommit(false);try(var q=c.prepareStatement("INSERT INTO app_users(id,username,password_hash,role) VALUES(?,?,?,?)")){q.setString(1,id);q.setString(2,name);q.setString(3,password);q.setString(4,role);q.executeUpdate();BusinessStore.audit(c,actor.username(),"USER_CREATED",name);c.commit();}catch(SQLException e){c.rollback();if(e.getSQLState().startsWith("23"))throw new WebApplicationException("Username already exists.",409);throw e;}}return Map.of("id",id,"username",name,"role",role,"active",true);}
 @PUT @Path("/users/{id}") public Object update(@PathParam("id")String id,JsonNode request)throws Exception{var actor=auth.user(authorization,token);auth.admin(actor);String role=role(request);if(!request.has("active")||!request.get("active").isBoolean())throw new BadRequestException("active must be true or false.");boolean active=request.get("active").asBoolean();if(id.equals(actor.id())&&(!active||!role.equals("Admin")))throw new BadRequestException("You cannot remove your own administrator access.");String password=ComplianceEngine.optional(request,"password",200);String hash=password.isEmpty()?null:AuthService.hash(password);try(var c=database.getConnection()){c.setAutoCommit(false);try(var q=c.prepareStatement("UPDATE app_users SET role=?,active=?,password_hash=COALESCE(?,password_hash) WHERE id=?")){q.setString(1,role);q.setBoolean(2,active);q.setString(3,hash);q.setString(4,id);if(q.executeUpdate()!=1)throw new NotFoundException("User was not found.");if(hash!=null||!active)try(var invalidate=c.prepareStatement("DELETE FROM app_sessions WHERE user_id=?")){invalidate.setString(1,id);invalidate.executeUpdate();}BusinessStore.audit(c,actor.username(),"USER_UPDATED",id);c.commit();}catch(Exception e){c.rollback();throw e;}}return Map.of("ok",true);}
 @POST @Path("/auth/password") public Object password(JsonNode request)throws Exception{var actor=auth.user(authorization,token);String current=ComplianceEngine.required(request,"currentPassword",200),replacement=AuthService.hash(ComplianceEngine.required(request,"newPassword",200));try(var c=database.getConnection()){c.setAutoCommit(false);try{try(var q=c.prepareStatement("SELECT password_hash FROM app_users WHERE id=? FOR UPDATE")){q.setString(1,actor.id());try(var r=q.executeQuery()){r.next();if(!AuthService.verify(current,r.getString(1)))throw new BadRequestException("Current password is incorrect.");}}try(var q=c.prepareStatement("UPDATE app_users SET password_hash=? WHERE id=?")){q.setString(1,replacement);q.setString(2,actor.id());q.executeUpdate();}try(var q=c.prepareStatement("DELETE FROM app_sessions WHERE user_id=?")){q.setString(1,actor.id());q.executeUpdate();}BusinessStore.audit(c,actor.username(),"PASSWORD_CHANGED",actor.id());c.commit();}catch(Exception e){c.rollback();throw e;}}return Map.of("ok",true);}
}
